import{creatureBuilder,paintCreatureMesh}from'./dungeon-creature-mesh.js';
export const MYSTIC_MATERIALS=Object.freeze({cloth:Object.freeze(['#f27f72','#ce2029','#591d35']),gold:Object.freeze(['#ffd95a','#e97c07','#9c3824']),dark:Object.freeze(['#5c627d','#374252','#161928'])});
const{cloth:C,gold:G,dark:D}=MYSTIC_MATERIALS;
const clamp=x=>Math.max(0,Math.min(1,x)),ease=x=>{x=clamp(x);return x*x*(3-2*x);},lerp=(a,b,t)=>a+(b-a)*t;
export const MYSTIC_YAWS=Object.freeze({down:0,se:-Math.PI/4,sw:Math.PI/4,right:-Math.PI/2,left:Math.PI/2,up:Math.PI});
function turn(p,pivot,a,axis='z'){const[x,y,z]=p.map((v,i)=>v-pivot[i]),c=Math.cos(a),s=Math.sin(a);return axis==='x'?[p[0],pivot[1]+y*c+z*s,pivot[2]-y*s+z*c]:[pivot[0]+x*c-y*s,pivot[1]+x*s+y*c,p[2]];}
export function mysticPose({time=0,beat=0,pose='idle',soft=false}={}){const u=(beat%4+4)%4/4,wave=Math.sin(u*Math.PI),casting=pose==='cast'||pose==='reveal',open=pose==='reveal'?ease(Math.sin(u*Math.PI)):0;return{breath:soft?0:Math.sin(time*1.8)*.30,headTilt:soft?0:Math.sin(time*1.1)*.022,cast:casting?(soft?.7:ease(wave)):0,open,hit:pose==='hit'?(soft?.15:Math.max(0,1-u*4)):0,recover:pose==='recover'?(soft?.2:Math.sin(u*Math.PI)*.3):0,dissolve:pose==='illusion'?.58:1,beatPulse:Math.pow(1-((beat%1+1)%1),3)};}
const oct=(w,d,z,k=2)=>{const a=w/2,b=d/2;return[[-a+k,-b,z],[a-k,-b,z],[a,-b+k,z],[a,b-k,z],[a-k,b,z],[-a+k,b,z],[-a,b-k,z],[-a,-b+k,z]];};
function rings(m,id,loops,ramp,xf,cap=true){for(let n=0;n<loops.length-1;n++)for(let i=0;i<loops[n].length;i++){const j=(i+1)%loops[n].length;m.face(id,[loops[n][i],loops[n][j],loops[n+1][j],loops[n+1][i]],ramp,xf);}if(cap){m.face(id,loops.at(-1),ramp,xf);m.face(id,[...loops[0]].reverse(),ramp,xf);}}
export function mysticMesh({time=0,beat=0,pose='idle',direction='down',yaw=MYSTIC_YAWS[direction]??0,soft=false,includeHidden=false}={}){const m=creatureBuilder({soft:true,includeHidden}),p=mysticPose({time,beat,pose,soft}),world=q=>turn(q,[0,0,0],yaw),upper=q=>{const a=turn(q,[0,0,24],p.hit*-.09+p.recover*.12,'x');return world([a[0],a[1],a[2]+p.breath]);},head=q=>upper(turn(q,[0,-1,36],p.headTilt,'x')),box=(id,x,y,z,w,d,h,ramp=C,b=1.5,xf=upper)=>m.box(id,x,y,z,w,d,h,ramp,b,xf);
 // Flared, anchored cloak: shape differences are actual tapered volumes.
 const body=[oct(36,28,3,3),oct(40,31,5,3),oct(30,24,22,2),oct(33,25,33,2),oct(29,21,36,2)].map(loop=>loop.map(([x,y,z])=>[x,y-2,z]));rings(m,'robe-body',body,C,world);
 for(const s of[-1,1]){const panel=world;rings(m,'robe-panel-'+s,[oct(13,2,1,.6).map(([x,y,z])=>[x+s*10,y+13.7,z]),oct(15,2.2,3,.6).map(([x,y,z])=>[x+s*10,y+13.7,z]),oct(10,1.5,20,.5).map(([x,y,z])=>[x+s*10,y+11.4,z])],C,panel);}
 // Hood shell is hollow: rim, return walls and inset face are separate surfaces.
 const outline=[[-13,60],[13,60],[19,54],[19,40],[13,34],[-13,34],[-19,40],[-19,54]],hole=[[-9,54],[9,54],[12,51],[12,42],[8,38],[-8,38],[-12,42],[-12,51]],at=(arr,y,s=1)=>arr.map(([x,z])=>[x*s,y,47+(z-47)*s]),shell=[at(outline,-15,.90),at(outline,-12),at(outline,11.5),at(outline,14,.93)];
 // Extrude the +Y-facing outline; edge winding keeps the shell normals outward.
 for(let n=0;n<shell.length-1;n++)for(let i=0;i<8;i++){const j=(i+1)%8;m.face('hood-shell',[shell[n][i],shell[n][j],shell[n+1][j],shell[n+1][i]],C,head);}m.face('hood-back',[...shell[0]].reverse(),C,head);
 const lip=at(hole,14.1),inner=at(hole,8,.88);for(let i=0;i<8;i++){const j=(i+1)%8;m.face('hood-rim',[shell[3][i],shell[3][j],lip[j],lip[i]],C,head);m.face('hood-inner',[lip[i],lip[j],inner[j],inner[i]],[C[2],C[2],D[2]],head);}m.face('hood-face',inner,D,head,D[2]);
 for(const s of[-1,1])box('eye-'+s,s*5.5,11.0,45,4.7,.5,3,[G[0],G[0],G[1]],.15,head);
 // Neck and front collar separate the hood from the mantle without a black outline.
 box('collar-back',0,-7,33,25,13,5,C,1.2);for(const s of[-1,1])box('collar-'+s,s*9,11,31,11,7,5,C,1, q=>upper(turn(q,[s*8,11,33],-s*.15,'z')));
 // Independent sleeves and compact golden hands, hinged at the shoulders.
 for(const s of[-1,1]){const arm=q=>{let a=turn(q,[s*18,0,34],-s*p.cast*.30,'z');a=turn(a,[s*18,0,34],-p.cast*.90+(soft?0:Math.sin(time*1.45+s)*.025),'x');return upper(a);};const sleeve=[oct(15,15,25,2),oct(20,18,27,2),oct(19,17,38,2),oct(14,13,41,2)].map(loop=>loop.map(([x,y,z])=>[x+s*26,y,z]));rings(m,'sleeve-'+s,sleeve,C,arm);box('cuff-'+s,s*29,7,25,12,11,4,G,.7,arm);box('cuff-inner-'+s,s*29,8,24.7,9,9,2,D,.5,arm);box('hand-'+s,s*31,10,20,10,11,8,G,1.5,arm);box('thumb-'+s,s*25.6,12,22,3.4,5,4,G,.7,arm);}
 // Existing square brooch becomes an explicit frame and two hinged plates.
 box('brooch-back',0,14.5,26,9,4,9,D,1);for(const s of[-1,1]){box('brooch-side-'+s,s*4,16,25.8,2,2.6,9.5,G,.5);box('brooch-edge-'+s,0,16,s<0?25.8:33.3,9,2.6,2,G,.5);}box('brooch-core',0,16.1,28,4.5,1.3,4.5,G,.5);
 for(const s of[-1,1]){const door=q=>upper(turn(q,[s*3,17.2,30],-s*p.open*1.25,'z'));box('brooch-door-'+s,s*1.5,17.2,27,3,1,6,C,.25,door);}
 // Crown keeps its three points and original maximum height (76).
 const outer=[oct(25,17,60),oct(27,19,61),oct(27,19,64),oct(25,17,65)],inside=[60,61,64,65].map(z=>oct(21,13,z,1));rings(m,'crown-band',outer,G,head,false);for(let n=0;n<3;n++)for(let i=0;i<8;i++){const j=(i+1)%8;m.face('crown-inside',[inside[n][j],inside[n][i],inside[n+1][i],inside[n+1][j]],G,head);}for(const n of[0,3])for(let i=0;i<8;i++){const j=(i+1)%8,q=[outer[n][i],outer[n][j],inside[n][j],inside[n][i]];m.face('crown-rim',n===3?q:q.reverse(),G,head);}box('crown-bridge',0,-1,60,22.2,3,5,G,.6,head);for(const x of[-10,0,10]){const h=x===0?12:8;const loops=[oct(7,9,64,1),oct(7,9,64.8,1),oct(5.6,7,64+h-1,1),oct(4,5.5,64+h,.8)].map(loop=>loop.map(([a,y,z])=>[a+x,y-1,z]));rings(m,'crown-point-'+x,loops,G,head);}
 const h0=head([0,0,45]),h1=head([0,1,45]),frontVisible=-(h1[0]-h0[0])/11+(h1[1]-h0[1])+(h1[2]-h0[2])*8/11>.0001;return m.finish().filter(f=>includeHidden||frontVisible||!f.id.startsWith('eye-'));}
export function paintMystic(c,n,x,y,width,time,{beat=0,soft=false,direction='down',yaw,pose='idle',shadow=true}={}){const p=mysticPose({time,beat,pose,soft}),mesh=mysticMesh({time,beat,pose,soft,direction,yaw});c.save();c.globalAlpha*=p.dissolve;paintCreatureMesh(c,mesh,x,y,width/83,{shadow,emissionIndex:3});if(p.open>.1&&direction!=='up'&&(yaw===undefined||Math.cos(yaw)>0)){const a=yaw??MYSTIC_YAWS[direction]??0,xx=-16.9*Math.sin(a),yy=16.9*Math.cos(a),px=x+(xx+yy/11)*width/83,py=y+(yy*8/11-30)*width/83;c.globalAlpha*=.18*p.open*(soft?.5:.5+p.beatPulse*.5);c.fillStyle=G[0];c.beginPath();c.ellipse(px,py,5*width/83,4*width/83,0,0,Math.PI*2);c.fill();}c.restore();return true;}
